const ROUTES={laya:"laya",njom:"njom",lna:"lna",scoop:"scoop",mukhtar:"mukhtar"};
function reply(request,body,type,status=200,cache="public, max-age=300"){
 const headers=new Headers({"content-type":type,"cache-control":cache,"x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin"});
 return new Response(request.method==="HEAD"?null:body,{status,headers});
}
export default {async fetch(request,env){
 const url=new URL(request.url),slug=ROUTES[url.hostname.split(".")[0]];
 if(!slug)return new Response("Unknown storefront",{status:404});
 const path=url.pathname,store=STORES[slug];
 if(path==="/api/health")return reply(request,JSON.stringify({ok:true,store:slug}),"application/json; charset=utf-8",200,"no-store");
 if(path==="/api/orders"&&request.method==="POST"){
  let b;
  try{
   if(Number(request.headers.get("content-length")||0)>12000)return reply(request,JSON.stringify({ok:false}),"application/json; charset=utf-8",413,"no-store");
   const raw=await request.text();
   if(raw.length>12000)return reply(request,JSON.stringify({ok:false}),"application/json; charset=utf-8",413,"no-store");
   b=JSON.parse(raw);
  }catch(_){return reply(request,JSON.stringify({ok:false}),"application/json; charset=utf-8",400,"no-store");}
  const name=typeof b.name==="string"?b.name.trim().slice(0,70):"",phone=typeof b.phone==="string"?b.phone.trim().slice(0,24):"",area=typeof b.area==="string"?b.area.trim().slice(0,100):"",note=typeof b.note==="string"?b.note.trim().slice(0,300):"";
  const items=Array.isArray(b.items)?b.items.slice(0,20).map(x=>({id:String(x.id||"").slice(0,80),name:String(x.name||"").slice(0,120),qty:Math.max(1,Math.min(20,Number(x.qty)||1))})).filter(x=>x.id&&x.name):[];
  if(!name||!phone||!area||!items.length)return reply(request,JSON.stringify({ok:false,error:"Complete order details"}),"application/json; charset=utf-8",400,"no-store");
  const id="ORD-"+crypto.randomUUID().slice(0,8).toUpperCase();
  try{
   const record={id,store:slug,name,phone,area,note,items,createdAt:new Date().toISOString(),status:"new"};
   await env.ORDERS.put(slug+":"+id,JSON.stringify(record),{metadata:{status:"new",createdAt:record.createdAt}});
   return reply(request,JSON.stringify({ok:true,id,store:slug}),"application/json; charset=utf-8",201,"no-store");
  }catch(e){console.error("order-save",String(e));return reply(request,JSON.stringify({ok:false,error:"Could not save order"}),"application/json; charset=utf-8",503,"no-store");}
 }
 if(path==="/api/orders")return reply(request,"Method not allowed","text/plain; charset=utf-8",405,"no-store");
 if(request.method!=="GET"&&request.method!=="HEAD")return reply(request,"Method not allowed","text/plain; charset=utf-8",405,"no-store");
 if(path==="/"||path==="/index.html")return reply(request,store.html,"text/html; charset=utf-8",200,"public, max-age=60, stale-while-revalidate=300");
 if(path==="/store.json")return reply(request,store.json,"application/json; charset=utf-8",200,"public, max-age=300");
 if(path==="/favicon.svg")return reply(request,store.favicon,"image/svg+xml; charset=utf-8",200,"public, max-age=3600");
 if(path==="/assets/storefront.js")return reply(request,JS,"application/javascript; charset=utf-8",200,"public, max-age=3600");
 if(path==="/assets/storefront.css")return reply(request,CSS,"text/css; charset=utf-8",200,"public, max-age=3600");
 return reply(request,"Not found","text/plain; charset=utf-8",404,"no-store");
}};
